/* Leonida Dossier — dark case-file theme. System fonts only, no network. */
*{box-sizing:border-box}
:root{
  --bg:#10151d; --bg2:#171e29; --panel:#1d2634; --panel2:#232f42;
  --ink:#f2ead8; --muted:#a9b4c4; --line:#33405a;
  --orange:#ff7a1a; --gold:#e8c15a; --plat:#dfe6ee;
  --green:#58c98a; --red:#ff5d5d; --silver:#c3ccd8; --bronze:#d08a4e;
}
html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);
  font-family:-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.45}
h1{font-family:Georgia,"Times New Roman",serif;letter-spacing:.06em;margin:0;font-size:30px;color:var(--ink)}
h2{font-size:17px;margin:0 0 8px}
h3{font-size:15px;margin:0 0 6px}
a{color:#ffb066}
button,select,input{font:inherit;color:var(--ink)}
button{cursor:pointer;background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:7px 12px}
